/**
 * 追加线程堆栈帧，并在相应帧标注等待/持有的锁与锁定的 monitor，最后追加锁定的同步器列表。
 * 对与 {@code lockIdentityHashCode} 匹配的锁高亮其阻塞的线程数。
 */
private static void appendStackTraceAndLocks(StringBuilder sb, StackTraceElement[] stackTrace, Thread.State state,
                                             LockInfo lockInfo, MonitorInfo[] lockedMonitors,
                                             LockInfo[] lockedSynchronizers, int lockIdentityHashCode,
                                             int blockingThreadCount) {
    int i = 0;
    for (StackTraceElement ste : stackTrace) {
        sb.append("\tat ").append(ste.toString());
        sb.append('\n');
        if (i == 0 && lockInfo != null) {
            switch (state) {
                case BLOCKED:
                    sb.append("\t-  blocked on ").append(lockInfo);
                    sb.append('\n');
                    break;
                case WAITING:
                    sb.append("\t-  waiting on ").append(lockInfo);
                    sb.append('\n');
                    break;
                case TIMED_WAITING:
                    sb.append("\t-  waiting on ").append(lockInfo);
                    sb.append('\n');
                    break;
                default:
            }
        }

        for (MonitorInfo mi : lockedMonitors) {
            if (mi.getLockedStackDepth() == i) {
                sb.append("\t-  locked ").append(mi);
                if (mi.getIdentityHashCode() == lockIdentityHashCode) {
                    Ansi highlighted = Ansi.ansi().fg(Ansi.Color.RED);
                    highlighted.a(" <---- but blocks ").a(blockingThreadCount).a(" other threads!");
                    sb.append(highlighted.reset().toString());
                }
                sb.append('\n');
            }
        }
        ++i;
    }
    if (i < stackTrace.length) {
        sb.append("\t...");
        sb.append('\n');
    }

    if (lockedSynchronizers.length > 0) {
        sb.append("\n\tNumber of locked synchronizers = ").append(lockedSynchronizers.length);
        sb.append('\n');
        for (LockInfo li : lockedSynchronizers) {
            sb.append("\t- ").append(li);
            if (li.getIdentityHashCode() == lockIdentityHashCode) {
                sb.append(" <---- but blocks ").append(blockingThreadCount);
                sb.append(" other threads!");
            }
            sb.append('\n');
        }
    }
}

