     */
    private static void appendThreadStateLine(StringBuilder sb, Thread.State state, String lockName,
                                              String lockOwnerName, long lockOwnerId, boolean suspended,
                                              boolean inNative) {
        sb.append(" ").append(state);

        if (lockName != null) {
            sb.append(" on ").append(lockName);
        }
        if (lockOwnerName != null) {
            sb.append(" owned by \"").append(lockOwnerName).append("\" Id=").append(lockOwnerId);
        }
